const input = $input.first().json;
const test = input.test_control;
if (!test) return [{ json: { ...input, agenda_route: input.operation } }];
if (test.execution_mode !== 'full_agent_virtual') throw new Error('agenda_test_mode_invalid');
const calendar = test.tool_policy?.calendar;
if (!['disabled','test_read_only','test_read_write'].includes(calendar)) throw new Error('agenda_test_calendar_policy_invalid');
if (calendar === 'disabled') return [{ json: { ...input, agenda_route: 'test.calendar.disabled' } }];
if (calendar === 'test_read_only' && input.operation === 'appointment.create') return [{ json: { ...input, agenda_route: 'test.calendar.read_only' } }];
return [{ json: { ...input, agenda_route: input.operation } }];

const input = $input.first().json;
return [{ json: {
  status: 'CALENDAR_DISABLED_IN_TEST',
  operation: input.operation,
  instrucao_apresentacao: 'A agenda está desativada neste teste. Informe que a consulta ou criação de horário não foi executada e não invente disponibilidade.',
  provider_send_attempted: false,
} }];

const input = $input.first().json;
return [{ json: {
  status: 'CALENDAR_READ_ONLY_IN_TEST',
  operation: input.operation,
  instrucao_apresentacao: 'O calendário deste teste permite somente consulta. Nenhum agendamento foi criado.',
  provider_send_attempted: false,
} }];

const TZ = 'America/New_York';
const input = $('OPERAÇÃO | Receber operação de agenda').first().json;
const servicoPedido = (input.servico || '').toString();
const variante = (input.variante || '').toString().trim();
const varianteConfirmada = (input.variante_confirmada || '').toString().trim().toLowerCase() === 'sim';
const dataPreferida = (input.data_preferida || '').toString().trim();
const periodo = (input.periodo_preferido || '').toString().trim().toLowerCase();

const norm = s => s.toString().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/_/g, ' ').trim();
const rows = $input.all().map(i => i.json);
const alvo = norm(servicoPedido);

let servico = rows.find(r => norm(r.nome) === alvo || norm(r.nome_en || '') === alvo || norm(r.nome_es || '') === alvo);
if (!servico) servico = rows.find(r => {
  let al = r.aliases;
  if (typeof al === 'string') { try { al = JSON.parse(al); } catch (e) { al = []; } }
  return (al || []).some(a => norm(a) === alvo) || norm(r.nome).includes(alvo) || alvo.includes(norm(r.nome));
});
if (!servico) return [{ json: { status: 'ERRO', mensagem: `Serviço "${servicoPedido}" não encontrado. Use consultar_servicos e passe o nome exato em português.` } }];

// requer_avaliacao => o que se agenda é a Consulta de Avaliação
let agendado = servico;
let observacao = '';
if (String(servico.requer_avaliacao) === 'true') {
  agendado = rows.find(r => norm(r.nome) === 'consulta de avaliacao') || servico;
  observacao = `"${servico.nome}" requer avaliação: o agendamento é da Consulta de Avaliação (US$ 40, 100% revertidos no primeiro tratamento).`;
}

// ===== matching inteligente de variante =====
// aceita: nome oficial ("padrao", "estendida"), pedaço do nome ("área média", "media")
// ou os MINUTOS ("60", "a de 60", "60 min") casando pelo valor cadastrado
function acharVariante(variantes, pedido) {
  if (!variantes || !pedido) return null;
  const p = norm(pedido);
  const chaves = Object.keys(variantes);
  let k = chaves.find(x => norm(x) === p);
  if (!k) k = chaves.find(x => p.includes(norm(x)) || norm(x).includes(p));
  if (k) return k;
  const num = (p.match(/\d+/) || [])[0];
  if (num) {
    k = chaves.find(x => Number(variantes[x]) === Number(num));
    if (!k) k = chaves.find(x => norm(x).includes(num));
    if (k) return k;
  }
  return null;
}

// ===== MÚLTIPLAS ÁREAS (ex.: Depilação a Laser) =====
// variante pode vir com várias áreas: "pequena + media", "axila, perna", "2 areas medias", etc.
// Regra de duração (confirmada pelo Samuel):
//   corpo inteiro em qualquer parte  => 150 min
//   3 ou mais áreas                  => 60 min fixo
//   2 áreas                          => SOMA das duas
//   1 área                           => valor da variante
function resolverAreas(variantes, pedido) {
  if (!variantes || !pedido) return null;
  // separa por vírgula, +, /, " e ", " y ", " and "
  const partes = pedido.split(/\s*(?:,|\+|\/|;)\s*|\s+(?:e|y|and)\s+/i)
    .map(p => p.trim()).filter(Boolean);
  const chavesAchadas = [];
  const numPorExtenso = { uma: 1, una: 1, one: 1, duas: 2, dos: 2, two: 2, tres: 3, three: 3, quatro: 4, cuatro: 4, four: 4 };
  for (const parte of partes) {
    // multiplicador tipo "2 areas medias" / "duas áreas pequenas" / "3 small areas"
    const pn = norm(parte);
    let mult = 1;
    let busca = parte;
    const mPref = pn.match(/^(\d+|uma|una|one|duas|dos|two|tres|three|quatro|cuatro|four)\s+areas?\s+(.+)$/);
    if (mPref) {
      mult = Number(mPref[1]) || numPorExtenso[mPref[1]] || 1;
      // remove plural das palavras restantes ("grandes" -> "grande") para casar com a chave
      busca = mPref[2].replace(/(\w)s(?=\s|$)/g, '$1');
    }
    const k = acharVariante(variantes, busca);
    if (!k) return { erro: parte };
    for (let i = 0; i < mult; i++) chavesAchadas.push(k);
  }
  if (!chavesAchadas.length) return null;
  const temCorpoInteiro = chavesAchadas.some(k => /corpo|full\s*body|cuerpo/.test(norm(k)) || Number(variantes[k]) >= 150);
  let dur;
  if (temCorpoInteiro) dur = 150;
  else if (chavesAchadas.length >= 3) dur = 60;
  else if (chavesAchadas.length === 2) dur = Number(variantes[chavesAchadas[0]]) + Number(variantes[chavesAchadas[1]]);
  else dur = Number(variantes[chavesAchadas[0]]);
  return { chaves: chavesAchadas, duracao: dur };
}

let variantes = agendado.duracao_variantes;
if (typeof variantes === 'string' && variantes) { try { variantes = JSON.parse(variantes); } catch (e) { variantes = null; } }
let duracao = null;
let varianteKey = null;

// GUARDRAIL: variante só vale se veio com variante_confirmada="sim"
// (o modelo tem histórico de assumir "padrão" sozinho — aqui isso é bloqueado)
if (variantes && variante && varianteConfirmada) {
  const res = resolverAreas(variantes, variante);
  if (res && !res.erro) {
    varianteKey = res.chaves.join(' + ');
    duracao = res.duracao;
  } else if (res && res.erro) {
    return [{ json: {
      status: 'VARIANTE_NECESSARIA',
      servico: servico.nome,
      variantes_disponiveis: Object.entries(variantes).map(([k, v]) => `${k} (${v} min)`),
      mensagem: `Não reconheci a área/variante "${res.erro}". Pergunte ao cliente qual(is) das opções disponíveis ele quer e chame de novo usando os nomes oficiais (ex.: area_pequena, area_media), separados por vírgula se forem várias.`
    } }];
  }
}
if (!duracao && variantes && Object.keys(variantes).length && agendado.id === servico.id) {
  return [{ json: {
    status: 'VARIANTE_NECESSARIA',
    servico: servico.nome,
    variantes_disponiveis: Object.entries(variantes).map(([k, v]) => `${k} (${v} min)`),
    mensagem: 'Este serviço tem variações de duração e o cliente ainda NÃO escolheu (ou a escolha não foi confirmada). Pergunte ao cliente qual(is) área(s) ele quer tratar, apresentando as opções. Se forem VÁRIAS áreas, colete TODAS antes de chamar de novo e passe-as separadas por vírgula (ex.: "area_pequena, area_media"). Só depois que ELE responder, chame de novo passando variante e variante_confirmada="sim". NUNCA escolha por ele.'
  } }];
}
if (!duracao) duracao = Number(agendado.duracao_agenda_min) || null;
if (!duracao) duracao = Math.min(150, Math.ceil((Number(agendado.duracao_max) || 60) / 30) * 30); // fallback

// janela de busca
const hoje = DateTime.now().setZone(TZ).startOf('day');
const minDia = hoje.plus({ days: 1 });
const maxDia = hoje.plus({ days: 60 });
let inicio = minDia;
if (dataPreferida) {
  const d = DateTime.fromISO(dataPreferida, { zone: TZ }).startOf('day');
  if (d.isValid) {
    if (d > maxDia) return [{ json: { status: 'FORA_DO_LIMITE', mensagem: 'Agendamos com no máximo 60 dias de antecedência. Peça uma data mais próxima.' } }];
    inicio = d < minDia ? minDia : d;
  }
}
let fim = inicio.plus({ days: 7 });
if (fim > maxDia) fim = maxDia;

return [{ json: {
  status: 'OK',
  servico_original: servico.nome,
  servico_agendado: agendado.nome,
  profissional: agendado.profissional,
  duracao_min: duracao,
  variante: varianteKey || variante || null,
  observacao,
  periodo_preferido: ['manha','tarde','noite'].includes(periodo) ? periodo : null,
  data_preferida_aplicada: dataPreferida || null,
  timeMin: inicio.toISO(),
  timeMax: fim.endOf('day').toISO()
} }];

const TZ = 'America/New_York';
const BUFFER = 15;
const cfg = $('DISPONIBILIDADE | Resolver Serviço e Janela').first().json;

// ===== DIAS BLOQUEADOS (pedido do Samuel) =====
// Dias em que a clínica NÃO aceita agendamento nenhum, para os dois
// profissionais. Formato: 'YYYY-MM-DD'. Para bloquear outro dia no futuro,
// basta acrescentar uma linha aqui.
const DIAS_BLOQUEADOS = [
  '2026-09-05', // sábado 05/09/2026 — bloqueado a pedido do Samuel (03/09)
];
// ==============================================

// formato americano de hora: 10:00 AM / 2:30 PM
const fmtHora = (d) => d.toFormat('h:mm a');

// ===== JANELA POR PROFISSIONAL =====
// A partir de 27/08/2026 (volta às aulas do Samuel), seg–sex a agenda do Samuel
// só aceita agendamento com INÍCIO entre 3:30 PM e 7:00 PM.
// Ter e qui, tudo tem de TERMINAR até 7:30 PM — na prática, começar às 7:00 PM
// nesses dias só cabe serviço de até 30 min (a "consulta rápida" do Samuel).
// Nos demais dias a sessão pode terminar até as 8:00 PM (fechamento).
// Sábado continua o dia todo (10 AM–8 PM). Bruna não muda.
// A regra usa a DATA DO SLOT, não a de hoje.
const VOLTA_AS_AULAS = DateTime.fromISO('2026-08-27', { zone: TZ });
function regraSamuelDia(dia) {
  return cfg.profissional === 'Samuel' &&
    dia >= VOLTA_AS_AULAS.startOf('day') &&
    dia.weekday >= 1 && dia.weekday <= 5;
}
// devolve os limites do dia em MINUTOS desde 00:00:
// iniMin/iniMax = janela de INÍCIO permitida; fimMax = hora máxima de TÉRMINO
function janelaDoDia(dia) {
  if (regraSamuelDia(dia)) {
    return {
      iniMin: 15 * 60 + 30, // 3:30 PM
      iniMax: 19 * 60,      // último início: 7:00 PM
      fimMax: (dia.weekday === 2 || dia.weekday === 4) ? 19 * 60 + 30 : 20 * 60
    };
  }
  return { iniMin: 10 * 60, iniMax: 20 * 60, fimMax: 20 * 60 };
}
// ===================================

// ----- horário específico pedido pelo cliente (opcional) -----
let horaPref = null;
try {
  const hpRaw = ($('OPERAÇÃO | Receber operação de agenda').first().json.horario_preferido || '').toString().trim();
  const m = hpRaw.match(/(\d{1,2})(?:\s*[:hH]\s*(\d{2}))?\s*(am|pm|a\.?m\.?|p\.?m\.?)?/i);
  if (hpRaw && m) {
    let h = Number(m[1]);
    const mn = m[2] ? Number(m[2]) : 0;
    const sufixo = (m[3] || '').toLowerCase().replace(/\./g, '');
    if (sufixo.startsWith('p') && h < 12) h += 12;
    if (sufixo.startsWith('a') && h === 12) h = 0;
    // sem sufixo: horas pequenas em clínica que abre às 10h são da tarde (2 = 14h)
    if (!sufixo && h >= 1 && h <= 7) h += 12;
    if (h >= 0 && h <= 23 && mn >= 0 && mn <= 59) horaPref = { h, mn };
  }
} catch (e) { horaPref = null; }
let pedido = null;

// ocupação por profissional (título define o dono; desconhecido bloqueia ambos)
const busy = { Samuel: [], Bruna: [] };
for (const item of $input.all()) {
  const ev = item.json;
  if (!ev || !ev.start) continue;
  const ini = DateTime.fromISO(ev.start.dateTime || ev.start.date, { zone: TZ });
  const fimEv = DateTime.fromISO(ev.end.dateTime || ev.end.date, { zone: TZ });
  const titulo = (ev.summary || '').trim();
  if (/^samuel\s*-/i.test(titulo)) busy.Samuel.push([ini, fimEv]);
  else if (/^bruna\s*-/i.test(titulo)) busy.Bruna.push([ini, fimEv]);
  else { busy.Samuel.push([ini, fimEv]); busy.Bruna.push([ini, fimEv]); }
}

const ocupado = busy[cfg.profissional] || [];
const dur = Number(cfg.duracao_min);
const periodos = { manha: [10, 12], tarde: [12, 17], noite: [17, 20] };
const nomesDias = ['segunda-feira','terça-feira','quarta-feira','quinta-feira','sexta-feira','sábado','domingo'];

function livre(ini, fim) {
  const a = ini.minus({ minutes: BUFFER });
  const b = fim.plus({ minutes: BUFFER });
  return !ocupado.some(([x, y]) => a < y && b > x);
}

const maxPorDia = cfg.data_preferida_aplicada ? 4 : 2;
const slots = [];
let dia = DateTime.fromISO(cfg.timeMin, { zone: TZ }).startOf('day');
const fimJanela = DateTime.fromISO(cfg.timeMax, { zone: TZ });

while (dia <= fimJanela && slots.length < 4) {
  const diaBloqueado = DIAS_BLOQUEADOS.includes(dia.toISODate());
  // cliente pediu exatamente um dia bloqueado → avisar o Agente com clareza
  if (diaBloqueado && !pedido && cfg.data_preferida_aplicada &&
      dia.hasSame(DateTime.fromISO(cfg.timeMin, { zone: TZ }), 'day')) {
    pedido = {
      status: 'INDISPONIVEL',
      pedido: `${nomesDias[dia.weekday - 1]}, ${dia.toFormat('dd/MM')}`,
      instrucao: 'O DIA INTEIRO pedido pelo cliente está indisponível (agenda bloqueada pela clínica). Diga brevemente que nesse dia não há horários — sem explicar o motivo e sem prometer encaixe — e ofereça as opcoes retornadas de outros dias, perguntando se alguma serve.'
    };
  }
  if (dia.weekday !== 7 && !diaBloqueado) { // domingo fechado; dias bloqueados idem
    const jan = janelaDoDia(dia);
    const [hIni, hFim] = cfg.periodo_preferido ? periodos[cfg.periodo_preferido] : [10, 20];
    // cruza o período pedido com a janela do profissional (tudo em minutos)
    const iniM = Math.max(hIni * 60, jan.iniMin);
    const limIniM = Math.min(hFim * 60, jan.iniMax);
    const fechamento = dia.startOf('day').plus({ minutes: jan.fimMax });
    const limiteInicio = dia.startOf('day').plus({ minutes: limIniM });

    // 1) coletar TODOS os inícios livres do dia (grade de 30 min)
    const livresDoDia = [];
    let t = dia.startOf('day').plus({ minutes: iniM });
    while (t <= limiteInicio) {
      const fimSlot = t.plus({ minutes: dur });
      if (fimSlot <= fechamento && livre(t, fimSlot)) livresDoDia.push(t);
      t = t.plus({ minutes: 30 });
    }

    // 2) checar o horário específico pedido pelo cliente (independe do período)
    let alvoPedido = null;
    // SÁBADO ANTES DAS 10 AM: a clínica está fechada, mas o Samuel avalia caso
    // a caso — o agente NÃO nega nem confirma: encaminha a solicitação.
    if (horaPref && !pedido && cfg.data_preferida_aplicada && dia.weekday === 6 &&
        (horaPref.h * 60 + horaPref.mn) < 10 * 60) {
      const alvoSab = dia.set({ hour: horaPref.h, minute: horaPref.mn });
      pedido = {
        status: 'ENCAMINHAR_EQUIPE',
        pedido: `${nomesDias[alvoSab.weekday - 1]} às ${fmtHora(alvoSab)}`,
        instrucao: 'O cliente pediu SÁBADO antes das 10:00 AM — fora do horário normal, mas o Samuel avalia esses casos. NÃO diga que não é possível e NÃO confirme: faça handoff prioridade "media" com serviço + sábado + horário pedido para o Samuel avaliar, e diga ao cliente que vai verificar essa possibilidade com a equipe e que ela retorna por aqui. NÃO ofereça as opcoes neste turno.'
      };
    }
    if (horaPref && !pedido) {
      const alvo = dia.set({ hour: horaPref.h, minute: horaPref.mn });
      const fimAlvo = alvo.plus({ minutes: dur });
      const naGrade = horaPref.mn % 30 === 0;
      const alvoM = horaPref.h * 60 + horaPref.mn;
      const dentro = alvoM >= jan.iniMin && alvoM <= jan.iniMax && fimAlvo <= fechamento;
      if (naGrade && dentro && livre(alvo, fimAlvo)) {
        alvoPedido = alvo;
        pedido = {
          status: 'DISPONIVEL',
          inicio_iso: alvo.toISO(),
          fim_iso: fimAlvo.toISO(),
          rotulo: `${nomesDias[alvo.weekday - 1]}, ${alvo.toFormat('dd/MM')} às ${fmtHora(alvo)}`,
          instrucao: 'O horário pedido pelo cliente ESTÁ livre e JÁ está escolhido. Use este inicio_iso e avance direto para pedir nome completo e WhatsApp. NÃO ofereça outras opções nem pergunte qual horário ele prefere.'
        };
      } else if (cfg.data_preferida_aplicada) {
        pedido = {
          status: 'INDISPONIVEL',
          pedido: `${nomesDias[alvo.weekday - 1]} às ${fmtHora(alvo)}`,
          instrucao: 'O horário pedido pelo cliente NÃO está livre. Diga isso brevemente (ex.: "infelizmente às ' + fmtHora(alvo) + ' não tenho") e ofereça as opcoes retornadas, perguntando se alguma serve.'
        };
      }
    }

    // 3) escolher até maxPorDia opções espalhadas (sempre inclui a primeira e a última)
    const restante = 4 - slots.length;
    const qtd = Math.min(maxPorDia, restante, livresDoDia.length);
    let escolhidos = [];
    if (qtd >= livresDoDia.length) {
      escolhidos = livresDoDia;
    } else if (qtd === 1) {
      escolhidos = [livresDoDia[0]];
    } else if (qtd > 1) {
      const idxUsados = new Set();
      for (let i = 0; i < qtd; i++) {
        idxUsados.add(Math.round(i * (livresDoDia.length - 1) / (qtd - 1)));
      }
      escolhidos = [...idxUsados].sort((a, b) => a - b).map(i => livresDoDia[i]);
    }

    // horário pedido disponível entra sempre, em primeiro lugar
    if (alvoPedido) {
      escolhidos = [alvoPedido, ...escolhidos.filter(x => +x !== +alvoPedido)].slice(0, Math.max(qtd, 1));
    }

    for (const s of escolhidos) {
      slots.push({
        inicio_iso: s.toISO(),
        fim_iso: s.plus({ minutes: dur }).toISO(),
        rotulo: `${nomesDias[s.weekday - 1]}, ${s.toFormat('dd/MM')} às ${fmtHora(s)}`
      });
    }
  }
  dia = dia.plus({ days: 1 });
}

if (!slots.length) return [{ json: {
  status: 'SEM_DISPONIBILIDADE',
  servico: cfg.servico_agendado,
  profissional: cfg.profissional,
  horario_pedido: pedido,
  mensagem: 'Nenhum horário livre nesse intervalo. Pergunte ao cliente outra data ou período.'
} }];

return [{ json: {
  status: 'OK',
  servico_original: cfg.servico_original,
  servico_agendado: cfg.servico_agendado,
  profissional: cfg.profissional,
  duracao_min: dur,
  variante: cfg.variante,
  observacao: cfg.observacao,
  horario_pedido: pedido,
  nota: 'IMPORTANTE: estas opções são apenas uma AMOSTRA dos horários livres. Um horário ausente da lista NÃO está ocupado. Se horario_pedido existir, siga a instrução dele. Nunca diga ao cliente que um horário foi preenchido por conta própria. Ao falar horários com o cliente, use SEMPRE o formato americano (10:00 AM, 2:30 PM) — nunca 14h ou 15:00.',
  opcoes: slots
} }];

const input = $input.first().json;
if (!input.servico || !input.invocation_id || !input.tool_invocation_id) throw new Error('availability_request_invalid');
return [{ json: input }];

const input = $('DISPONIBILIDADE | Validar solicitação de disponibilidade').first().json;
return [{ json: { status: 'OK', availability: $input.all().map((item) => item.json),
  tool_audit: [{ invocation_id: input.tool_invocation_id, operation: 'availability.check', result: 'succeeded' }], domain_events: [] } }];

const input = $('DISPONIBILIDADE | Validar solicitação de disponibilidade').first().json;
return [{ json: { status: 'ERRO', message: $input.first().json.mensagem || 'availability_failed',
  tool_audit: [{ invocation_id: input.tool_invocation_id, operation: 'availability.check', result: 'failed' }], domain_events: [] } }];

const TZ = 'America/New_York';
const input = $('OPERAÇÃO | Receber operação de agenda').first().json;
const norm = s => s.toString().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/_/g, ' ').trim();
const rows = $input.all().map(i => i.json);
const alvo = norm((input.servico || '').toString());

let servico = rows.find(r => norm(r.nome) === alvo || norm(r.nome_en || '') === alvo || norm(r.nome_es || '') === alvo);
if (!servico) servico = rows.find(r => {
  let al = r.aliases;
  if (typeof al === 'string') { try { al = JSON.parse(al); } catch (e) { al = []; } }
  return (al || []).some(a => norm(a) === alvo) || norm(r.nome).includes(alvo) || alvo.includes(norm(r.nome));
});
if (!servico) return [{ json: { status: 'ERRO', mensagem: `Serviço "${input.servico}" não encontrado.` } }];

let agendado = servico;
if (String(servico.requer_avaliacao) === 'true') {
  agendado = rows.find(r => norm(r.nome) === 'consulta de avaliacao') || servico;
}

// ===== matching inteligente de variante (igual ao Resolver) =====
function acharVariante(variantes, pedido) {
  if (!variantes || !pedido) return null;
  const p = norm(pedido);
  const chaves = Object.keys(variantes);
  let k = chaves.find(x => norm(x) === p);
  if (!k) k = chaves.find(x => p.includes(norm(x)) || norm(x).includes(p));
  if (k) return k;
  const num = (p.match(/\d+/) || [])[0];
  if (num) {
    k = chaves.find(x => Number(variantes[x]) === Number(num));
    if (!k) k = chaves.find(x => norm(x).includes(num));
    if (k) return k;
  }
  return null;
}

// ===== MÚLTIPLAS ÁREAS (igual ao Resolver Serviço e Janela) =====
// Regra de duração (confirmada pelo Samuel):
//   corpo inteiro em qualquer parte  => 150 min
//   3 ou mais áreas                  => 60 min fixo
//   2 áreas                          => SOMA das duas
//   1 área                           => valor da variante
function resolverAreas(variantes, pedido) {
  if (!variantes || !pedido) return null;
  const partes = pedido.split(/\s*(?:,|\+|\/|;)\s*|\s+(?:e|y|and)\s+/i)
    .map(p => p.trim()).filter(Boolean);
  const chavesAchadas = [];
  const numPorExtenso = { uma: 1, una: 1, one: 1, duas: 2, dos: 2, two: 2, tres: 3, three: 3, quatro: 4, cuatro: 4, four: 4 };
  for (const parte of partes) {
    const pn = norm(parte);
    let mult = 1;
    let busca = parte;
    const mPref = pn.match(/^(\d+|uma|una|one|duas|dos|two|tres|three|quatro|cuatro|four)\s+areas?\s+(.+)$/);
    if (mPref) {
      mult = Number(mPref[1]) || numPorExtenso[mPref[1]] || 1;
      busca = mPref[2].replace(/(\w)s(?=\s|$)/g, '$1');
    }
    const k = acharVariante(variantes, busca);
    if (!k) return { erro: parte };
    for (let i = 0; i < mult; i++) chavesAchadas.push(k);
  }
  if (!chavesAchadas.length) return null;
  const temCorpoInteiro = chavesAchadas.some(k => /corpo|full\s*body|cuerpo/.test(norm(k)) || Number(variantes[k]) >= 150);
  let dur;
  if (temCorpoInteiro) dur = 150;
  else if (chavesAchadas.length >= 3) dur = 60;
  else if (chavesAchadas.length === 2) dur = Number(variantes[chavesAchadas[0]]) + Number(variantes[chavesAchadas[1]]);
  else dur = Number(variantes[chavesAchadas[0]]);
  return { chaves: chavesAchadas, duracao: dur };
}

let variantes = agendado.duracao_variantes;
if (typeof variantes === 'string' && variantes) { try { variantes = JSON.parse(variantes); } catch (e) { variantes = null; } }
const variante = (input.variante || '').toString().trim();
let duracao = null;
let varianteKey = null;
if (variantes && variante) {
  const res = resolverAreas(variantes, variante);
  if (res && !res.erro) {
    varianteKey = res.chaves.join(' + ');
    duracao = res.duracao;
  } else if (res && res.erro) {
    return [{ json: { status: 'ERRO', mensagem: `Área/variante "${res.erro}" não reconhecida. Opções: ` + Object.entries(variantes).map(([k, v]) => `${k} (${v} min)`).join(', ') + '. Use os nomes oficiais, separados por vírgula se forem várias áreas, e passe EXATAMENTE a mesma variante usada em verificar_disponibilidade.' } }];
  }
}
if (!duracao && variantes && Object.keys(variantes).length && agendado.id === servico.id) {
  return [{ json: { status: 'ERRO', mensagem: 'Este serviço exige variante (área). Opções: ' + Object.entries(variantes).map(([k, v]) => `${k} (${v} min)`).join(', ') + '. Pergunte ao cliente qual(is) área(s) quer tratar e chame novamente passando todas separadas por vírgula.' } }];
}
if (!duracao) duracao = Number(agendado.duracao_agenda_min) || Math.min(150, Math.ceil((Number(agendado.duracao_max) || 60) / 30) * 30);

// ===== GUARDRAIL: nome e telefone reais, dados pelo cliente =====
const nomeIn = (input.nome || '').toString().trim();
const telIn = (input.telefone || '').toString().trim();
const digitos = telIn.replace(/\D/g, '');
const nomeNorm = norm(nomeIn);
const nomesProibidos = ['teste', 'lexia', 'cliente', 'contato', 'usuario', 'user', 'admin'];
if (!nomeIn || nomeIn.split(/\s+/).length < 2) {
  return [{ json: { status: 'ERRO', mensagem: 'Nome completo obrigatório (nome e sobrenome). Pergunte ao cliente o nome completo antes de criar.' } }];
}
if (nomesProibidos.some(p => nomeNorm.includes(p))) {
  return [{ json: { status: 'ERRO', mensagem: 'Este nome é um registro interno do sistema, NÃO é o nome do cliente. Pergunte o nome completo ao cliente no chat antes de criar.' } }];
}
if (digitos.length < 8 || digitos.length > 15 || /[a-z]/i.test(telIn.replace(/[x ()+-]/gi, ''))) {
  return [{ json: { status: 'ERRO', mensagem: 'Telefone inválido — isso não é um número de telefone. Peça ao cliente o número de WhatsApp; NUNCA use o ID do contato.' } }];
}
// ================================================================

// validar o horário pedido
const inicio = DateTime.fromISO((input.inicio_iso || '').toString(), { setZone: true }).setZone(TZ);
if (!inicio.isValid) return [{ json: { status: 'ERRO', mensagem: 'inicio_iso inválido. Use exatamente o inicio_iso retornado por verificar_disponibilidade.' } }];
const fim = inicio.plus({ minutes: duracao });
const hoje = DateTime.now().setZone(TZ).startOf('day');
const erros = [];
if (inicio.startOf('day') < hoje.plus({ days: 1 })) erros.push('horário no passado ou para hoje');
if (inicio.startOf('day') > hoje.plus({ days: 60 })) erros.push('mais de 60 dias de antecedência');
if (inicio.weekday === 7) erros.push('domingo não há agenda');
if (inicio.hour < 10 || fim > inicio.startOf('day').set({ hour: 20 })) erros.push('fora do horário de funcionamento');
if (inicio.minute % 30 !== 0) erros.push('fora da grade de 30 minutos');
// ===== JANELA DO SAMUEL (volta às aulas, a partir de 27/08/2026) =====
// Seg–sex a agenda do Samuel só aceita INÍCIO entre 3:30 PM e 7:00 PM.
// Ter e qui tudo tem de TERMINAR até 7:30 PM (às 7:00 PM só cabe serviço de
// até 30 min — a consulta rápida); demais dias, término até 8:00 PM.
// Sábado continua o dia todo. Bruna não muda. Espelho da regra do Calcular
// Slots em verificar_disponibilidade — se as duas divergirem, esta manda.
const VOLTA_AS_AULAS = DateTime.fromISO('2026-08-27', { zone: TZ });
if (
  agendado.profissional === 'Samuel' &&
  inicio.startOf('day') >= VOLTA_AS_AULAS.startOf('day') &&
  inicio.weekday >= 1 && inicio.weekday <= 5
) {
  const minutosInicio = inicio.hour * 60 + inicio.minute;
  if (minutosInicio < 15 * 60 + 30 || minutosInicio > 19 * 60) {
    erros.push('a agenda do Samuel em dia de semana só aceita início entre 3:30 PM e 7:00 PM');
  }
  const fimMax = (inicio.weekday === 2 || inicio.weekday === 4) ? 19 * 60 + 30 : 20 * 60;
  if (fim > inicio.startOf('day').plus({ minutes: fimMax })) {
    erros.push('às terças e quintas a sessão do Samuel precisa terminar até 7:30 PM — este serviço não cabe nesse horário');
  }
}
// =====================================================================
if (erros.length) return [{ json: { status: 'ERRO', mensagem: `Horário inválido (${erros.join('; ')}). Chame verificar_disponibilidade novamente e ofereça apenas opções retornadas.` } }];

const idioma = ['pt', 'en', 'es'].includes((input.idioma || '').toString().toLowerCase()) ? input.idioma.toLowerCase() : 'pt';

return [{ json: {
  status: 'OK',
  servico_original: servico.nome,
  servico_agendado: agendado.nome,
  servico_nome_en: agendado.nome_en, servico_nome_es: agendado.nome_es,
  profissional: agendado.profissional,
  duracao_min: duracao,
  variante: varianteKey || variante || null,
  inicio: inicio.toISO(), fim: fim.toISO(),
  nome: nomeIn,
  telefone: telIn,
  email: (input.email || '').toString().trim() || null,
  resumo_queixa: (input.resumo_queixa || '').toString().trim(),
  idioma,
  timeMin: inicio.startOf('day').toISO(),
  timeMax: inicio.startOf('day').plus({ days: 3 }).endOf('day').toISO()
} }];

const TZ = 'America/New_York';
const BUFFER = 15;
const cfg = $('AGENDAMENTO | Validar Pedido').first().json;

const busy = { Samuel: [], Bruna: [] };
for (const item of $input.all()) {
  const ev = item.json;
  if (!ev || !ev.start) continue;
  const ini = DateTime.fromISO(ev.start.dateTime || ev.start.date, { zone: TZ });
  const fimEv = DateTime.fromISO(ev.end.dateTime || ev.end.date, { zone: TZ });
  const titulo = (ev.summary || '').trim();
  if (/^samuel\s*-/i.test(titulo)) busy.Samuel.push([ini, fimEv]);
  else if (/^bruna\s*-/i.test(titulo)) busy.Bruna.push([ini, fimEv]);
  else { busy.Samuel.push([ini, fimEv]); busy.Bruna.push([ini, fimEv]); }
}
const ocupado = busy[cfg.profissional] || [];
const dur = Number(cfg.duracao_min);

function livre(ini, fim) {
  const a = ini.minus({ minutes: BUFFER });
  const b = fim.plus({ minutes: BUFFER });
  return !ocupado.some(([x, y]) => a < y && b > x);
}

const inicio = DateTime.fromISO(cfg.inicio, { zone: TZ });
const fim = DateTime.fromISO(cfg.fim, { zone: TZ });

if (livre(inicio, fim)) return [{ json: { ...cfg, status: 'LIVRE' } }];

// conflito: gerar alternativas nos próximos 3 dias
const nomesDias = ['segunda-feira','terça-feira','quarta-feira','quinta-feira','sexta-feira','sábado','domingo'];
const novas = [];
let dia = inicio.startOf('day');
const fimJanela = DateTime.fromISO(cfg.timeMax, { zone: TZ });
while (dia <= fimJanela && novas.length < 4) {
  if (dia.weekday !== 7) {
    let t = dia.set({ hour: 10, minute: 0 });
    let doDia = 0;
    while (t.plus({ minutes: dur }) <= dia.set({ hour: 20 }) && novas.length < 4 && doDia < 2) {
      const f = t.plus({ minutes: dur });
      if (livre(t, f)) {
        novas.push({ inicio_iso: t.toISO(), rotulo: `${nomesDias[t.weekday - 1]}, ${t.toFormat('dd/MM')} às ${t.toFormat('HH:mm')}` });
        doDia++; t = t.plus({ minutes: 120 });
      } else t = t.plus({ minutes: 30 });
    }
  }
  dia = dia.plus({ days: 1 });
}
return [{ json: { status: 'CONFLITO', mensagem: 'O horário acabou de ser ocupado. Peça desculpas breves e ofereça as novas opções.', novas_opcoes: novas } }];

const TZ = 'America/New_York';
const cfg = $('AGENDAMENTO | Validar Pedido').first().json;
const input = $('OPERAÇÃO | Receber operação de agenda').first().json;

if ((input.ignorar_duplicado || '').toString().toLowerCase() === 'sim') return [{ json: cfg }];

const dig = s => (s || '').toString().replace(/\D/g, '');
const norm = s => (s || '').toString().toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();

const tel = dig(cfg.telefone);
const servicoNovo = norm(cfg.servico_agendado);
const agora = DateTime.now().setZone(TZ);
const dups = [];

for (const item of $input.all()) {
  const r = item.json;
  if (!r || !r.telefone || dig(r.telefone) !== tel) continue;
  if (norm(r.servico) !== servicoNovo) continue; // serviço diferente = agendamento legítimo, passa
  const ini = DateTime.fromISO(r.inicio, { zone: TZ }).setZone(TZ);
  if (ini > agora) dups.push(`${r.servico} em ${ini.toFormat('dd/MM')} às ${ini.toFormat('HH:mm')} com ${r.profissional}`);
}

if (dups.length) return [{ json: {
  status: 'JA_AGENDADO',
  agendamentos_existentes: dups,
  mensagem: 'Cliente já tem este MESMO serviço agendado no futuro. Informe e pergunte: se ele realmente quer as duas sessões, chame novamente com ignorar_duplicado="sim"; se quer TROCAR a existente, é remarcação → handoff "media".'
} }];

return [{ json: cfg }];

const input = $input.first().json;
for (const field of ['servico','inicio_iso','nome','telefone','idioma','invocation_id','tool_invocation_id']) if (!String(input[field] || '').trim()) throw new Error('appointment_request_missing_' + field);
if (!input.scope || input.scope.cliente_slug !== 'miranda_skin_experts') throw new Error('appointment_scope_invalid');
return [{ json: input }];

const request = $('AGENDAMENTO | Validar contrato de criação').first().json;
const calendar = $('AGENDAMENTO | Create an event').first().json;
const cfg = $('AGENDAMENTO | Checar Conflito').first().json;
const appointmentRef = String(calendar.id || '').trim();
if (!appointmentRef || !cfg.inicio || !cfg.fim) throw new Error('appointment_effect_not_confirmed');
const eventId = (() => {
  const seedText = String(request.tool_invocation_id + ':appointment:confirmed');
  let h1 = 0x811c9dc5, h2 = 0x9e3779b9;
  for (let i = 0; i < seedText.length; i++) {
    h1 = Math.imul(h1 ^ seedText.charCodeAt(i), 0x01000193) >>> 0;
    h2 = Math.imul(h2 ^ (seedText.charCodeAt(i) + i), 0x85ebca6b) >>> 0;
  }
  const hex = [h1, h2, h1 ^ h2, Math.imul(h1, 31) ^ h2]
    .map((n) => (n >>> 0).toString(16).padStart(8, '0')).join('');
  return hex.slice(0,8) + '-' + hex.slice(8,12) + '-4' + hex.slice(13,16) + '-8' + hex.slice(17,20) + '-' + hex.slice(20,32);
})();
const domain = { schema_version: 'lexia.domain.event.v1', event_id: eventId, invocation_id: request.invocation_id,
  idempotency_key: 'appointment:' + appointmentRef + ':confirmed', type: 'appointment.confirmed', occurred_at: new Date().toISOString(),
  appointment: { appointment_ref: appointmentRef, status: 'confirmed', starts_at: cfg.inicio, ends_at: cfg.fim,
    timezone: $env.LEXIA_MIRANDA_TIMEZONE || 'America/New_York', tool_invocation_id: request.tool_invocation_id } };
return [{ json: { status: 'CRIADO', appointment_ref: appointmentRef, starts_at: cfg.inicio, ends_at: cfg.fim,
  confirmation_text: 'Agendamento confirmado.',
  tool_audit: [{ invocation_id: request.tool_invocation_id, operation: 'appointment.create', result: 'succeeded', appointment_ref: appointmentRef }],
  domain_events: [domain] } }];

const request = $('AGENDAMENTO | Validar contrato de criação').first().json;
const value = $input.first().json || {};
return [{ json: { status: value.status || 'ERRO', message: value.mensagem || 'appointment_creation_failed', reconciliation_required: Boolean(value.error),
  tool_audit: [{ invocation_id: request.tool_invocation_id, operation: 'appointment.create', result: 'failed' }], domain_events: [] } }];
